import {mealDishKey} from '../services/meal-supplement.js'
import { useMealCapture } from '../composables/use-meal-capture.js'
const props=defineProps({route:{type:Object,default:()=>({})},embedded:Boolean,entry:Object})
const {
 captureDishLabel,captureSummary,matchCarriedDish,removeCarriedDish,sourcePhoto,expectedDishes,entryKey,entryBlocked,currentMealContext,members,people,dishes,captureScope,mealType,
 date,time,oil,photo,error,notice,busy,editing,
 source,saved,pendingGroup,membersLoading,photoPreparing,localPhotoPending,supplement,editingRecord,
 extraPhotos,supplementSaver,vision,photoClient,saver,nutrition,nutritionClient,adjusting,
 mapping,sourceQuery,gramInput,portionCount,acceptMissing,familyOpen,photoOpen,nutritionRows,
 preview,previewReady,incomplete,nutrients,consent,origin,portionDraft,portionError,
 manualOpen,manualText,manualError,menuNotice,mealKeys,portions,oils,locked,
 selected,hasDishes,captureLocked,canSave,queueNutrition,refreshNutrition,amount,dishEnergy,
 pollResult,authorizeAndAnalyze,openMapping,searchSources,chooseSource,matchCandidates,applyServings,portionLabel,
